#!/usr/bin/env python3
"""Write reproducible coverage/build evidence for the encounter import."""
import json
from pathlib import Path
from encounter_data import ROOT,CACHE
r=json.loads((CACHE/'wikidex-encounters/report.json').read_text());names=json.loads((CACHE/'wikidex-encounters/resolved-names.json').read_text());wiki=json.loads((CACHE/'wikidex-encounters/index.json').read_text())
label_status={}
def add_label(name,status):
    if name not in label_status or status=='wikidex':label_status[name]=status
for rec in names['locations'].values():add_label(rec['name_es'],rec['status'])
for rec in names['areas'].values():add_label(rec['area_es'],rec['status'])
for rec in names['evidence'].values():
    for name in rec['areas']:
        if name!='Ubicación no especificada':add_label(name,'wikidex')
counts={status:sum(s==status for s in label_status.values()) for status in ['wikidex','translated']}
assets=ROOT/'app/assets';species=[json.loads(p.read_text()) for p in (assets/'data/pokemon').glob('*.json')]
new_bytes=sum(p.stat().st_size for p in (assets/'data/pokemon').glob('*.json'));old_bytes=json.loads((CACHE/'wikidex-encounters/asset-size-before.json').read_text())['pokemon_json_bytes']
lines=['# ZONA: cached all-game encounter index','',f"Imported {len(wiki['species'])} WikiDex species templates; {sum(bool(d['encounters']) for d in species if d['id']==d['species'])} national species and {sum(bool(d['encounters']) for d in species if d['id']!=d['species'])} forms have at least one recorded encounter.",'',f"{r['csv_rows_after_dedup']:,} retained CSV rows plus {r['wikidex_rows']:,} WikiDex rows = {r['csv_rows_after_dedup']+r['wikidex_rows']:,} total. Exact duplicates removed. Levels remain null when unspecified.",'',f"Pokemon record assets: {old_bytes/1048576:.2f} → {new_bytes/1048576:.2f} MiB (before APK compression); no image assets added.",'','## Spanish name provenance','',f"CSV-used location names: **{r['location_names'].get('wikidex',0)} WikiDex / {r['location_names'].get('translated',0)} translated** (563 location IDs).",'',f"Detailed CSV area names: **{r['area_names'].get('wikidex',0)} WikiDex / {r['area_names'].get('translated',0)} translated**. A WikiDex location combined with a translated floor/subarea counts as translated.",'',f"WikiDex-only supplements additionally use **{r['wikidex_supplement_area_names']}** distinct Spanish area labels (may overlap CSV names; includes explicit region-wide source prose and unspecified locations). No unresolved location translations; {sum('(sector ' in a['area_es'] for a in names['areas'].values())} numeric fallback sector names.",'','Every matched name has its page URL; each supplemented species/version has its page URL and revision ID in `cache/wikidex-encounters/resolved-names.json`. All raw API requests/responses are cached. Translated fallbacks are explicitly marked `translated`.','', '## Per-game coverage','', 'Counts are distinct national species, alternate forms, and display areas, not encounter probabilities or exhaustive availability.','', '| Version | Game | Species | Forms | Areas | Rows |','|---:|---|---:|---:|---:|---:|']
lines.insert(lines.index('## Spanish name provenance')+2,f"Across the complete index, deduplicating identical Spanish location/area labels: **{counts['wikidex']} WikiDex / {counts['translated']} translated**. The generic unspecified-location placeholder is excluded; if a label has both provenances, the explicit WikiDex evidence takes precedence.\n")
for g in r['games']:lines.append(f"| {g['version']} | {g['name']} | {g['species']} | {g['forms']} | {g['areas']} | {g['rows']} |")
lines+=['','## Controls and limits','','ZONA: OK next game group; 0 previous; up/down three rows per page. Left/right changes tabs. F-key roles are unchanged; the selected game is saved with the journal. Empty combinations show `Sin datos para este juego`.','','This is a location index. Slot rates, time/weather/season prerequisites and conditional spawns are not retained; the screen warns that conditions may apply. Gifts, trades, evolution and transfers are excluded. WikiDex rows retain stated methods but never invent missing levels. Forms only receive exact CSV form records, never inferred species-page encounters.','','WikiDex supplements currently fill species/version pairs with no CSV wild rows. They do not add extra missing locations where that pair already has CSV wild data. The conservative parser accepts explicit wild/pesca/Surf/Pokéradar/alfa/manada/outbreak/Dinamax/Teraincursión/underground/island-scan bullets and links to cached place pages; explicit short region-wide habitat prose is retained; other unstructured prose and ambiguous form clauses are skipped. Full availability of every species/form cannot be claimed.','','Noroteo and Academia Arándano categories explicitly separate Scarlet/Violet DLC locations. Luminalia Dimensional pages separate Mega Dimension. Base-game clauses that do not identify a DLC location are not guessed into DLC versions.','','No phone access, adb, flash or ROM build was performed. The APK is not hardware verified.','','## Changed encounter source files','','- `templates/src/org/kyf37/pokedex/PokedexActivity.java`','- `tools/fetch_data.py`','- `tools/verify_data.py`','- `tools/scrape_wikidex_encounters.py`','- `tools/encounter_data.py`','- `tools/apply_all_game_encounters.py`','- `tools/test_encounters.py`','- `tools/write_encounter_report.py`','- `README.md`','','Cached additions: `cache/wikidex-encounters/` (raw replies, index, translations, resolved names and report). Generated assets: all 1219 Pokémon JSON records, `data/encounter-games.json` and updated content manifest. `app/` was generated only via tools.','','## Verification final lines','']
for logfile in ['encounters-test.log','verify-data-all-games.log','host-test-all-games.log','verify-model-final.log','build-ui.log','verify-apk-final.log']:
    p=ROOT/logfile
    fresh=p.exists() and (logfile not in ['build-ui.log','host-test-all-games.log'] or p.stat().st_mtime>=(CACHE/'wikidex-encounters/index.json').stat().st_mtime)
    lines+=['### '+logfile,'','```text']+(p.read_text(errors='replace').splitlines()[-6:] if fresh else ['Pending: current combined validation has not completed'])+['```','']
(ROOT/'ENCOUNTERS-REPORT.md').write_text('\n'.join(lines)+'\n')
print('REPORT_READY',ROOT/'ENCOUNTERS-REPORT.md')
